class Solution {
    private TreeSet<int[]> l = new TreeSet<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
    private TreeSet<int[]> r = new TreeSet<>(l.comparator());
    private Map<Integer, Integer> cnt = new HashMap<>();
    private long s;

    public long[] findXSum(int[] nums, int k, int x) {
        int n = nums.length;
        long[] ans = new long[n - k + 1];
        for (int i = 0; i < n; ++i) {
            int v = nums[i];
            remove(v);
            cnt.merge(v, 1, Integer::sum);
            add(v);
            int j = i - k + 1;
            if (j < 0) {
                continue;
            }
            while (!r.isEmpty() && l.size() < x) {
                var p = r.pollLast();
                s += 1L * p[0] * p[1];
                l.add(p);
            }
            while (l.size() > x) {
                var p = l.pollFirst();
                s -= 1L * p[0] * p[1];
                r.add(p);
            }
            ans[j] = s;

            remove(nums[j]);
            cnt.merge(nums[j], -1, Integer::sum);
            add(nums[j]);
        }
        return ans;
    }

    private void remove(int v) {
        if (!cnt.containsKey(v)) {
            return;
        }
        var p = new int[] {cnt.get(v), v};
        if (l.contains(p)) {
            l.remove(p);
            s -= 1L * p[0] * p[1];
        } else {
            r.remove(p);
        }
    }

    private void add(int v) {
        if (!cnt.containsKey(v)) {
            return;
        }
        var p = new int[] {cnt.get(v), v};
        if (!l.isEmpty() && l.comparator().compare(l.first(), p) < 0) {
            l.add(p);
            s += 1L * p[0] * p[1];
        } else {
            r.add(p);
        }
    }
}

class Solution {
public:
    vector<long long> findXSum(vector<int>& nums, int k, int x) {
        using pii = pair<int, int>;
        set<pii> l, r;
        long long s = 0;
        unordered_map<int, int> cnt;
        auto add = [&](int v) {
            if (cnt[v] == 0) {
                return;
            }
            pii p = {cnt[v], v};
            if (!l.empty() && p > *l.begin()) {
                s += 1LL * p.first * p.second;
                l.insert(p);
            } else {
                r.insert(p);
            }
        };
        auto remove = [&](int v) {
            if (cnt[v] == 0) {
                return;
            }
            pii p = {cnt[v], v};
            auto it = l.find(p);
            if (it != l.end()) {
                s -= 1LL * p.first * p.second;
                l.erase(it);
            } else {
                r.erase(p);
            }
        };
        vector<long long> ans;
        for (int i = 0; i < nums.size(); ++i) {
            remove(nums[i]);
            ++cnt[nums[i]];
            add(nums[i]);

            int j = i - k + 1;
            if (j < 0) {
                continue;
            }

            while (!r.empty() && l.size() < x) {
                pii p = *r.rbegin();
                s += 1LL * p.first * p.second;
                r.erase(p);
                l.insert(p);
            }
            while (l.size() > x) {
                pii p = *l.begin();
                s -= 1LL * p.first * p.second;
                l.erase(p);
                r.insert(p);
            }
            ans.push_back(s);

            remove(nums[j]);
            --cnt[nums[j]];
            add(nums[j]);
        }
        return ans;
    }
};

func findXSum(nums []int, k int, x int) []int64 {
	type pair struct{ cnt, v int }
	cmpFn := func(a, b pair) int { return cmp.Or(a.cnt-b.cnt, a.v-b.v) }
	l := redblacktree.NewWith[pair, struct{}](cmpFn)
	r := redblacktree.NewWith[pair, struct{}](cmpFn)
	cnt := map[int]int{}
	var s int64

	add := func(v int) {
		if cnt[v] == 0 {
			return
		}
		p := pair{cnt[v], v}
		if !l.Empty() && cmpFn(l.Left().Key, p) < 0 {
			s += int64(p.cnt) * int64(p.v)
			l.Put(p, struct{}{})
		} else {
			r.Put(p, struct{}{})
		}
	}
	remove := func(v int) {
		if cnt[v] == 0 {
			return
		}
		p := pair{cnt[v], v}
		if _, ok := l.Get(p); ok {
			s -= int64(p.cnt) * int64(p.v)
			l.Remove(p)
		} else {
			r.Remove(p)
		}
	}

	n := len(nums)
	ans := make([]int64, 0, n-k+1)
	for i, v := range nums {
		remove(v)
		cnt[v]++
		add(v)
		j := i - k + 1
		if j < 0 {
			continue
		}
		for !r.Empty() && l.Size() < x {
			p := r.Right().Key
			s += int64(p.cnt) * int64(p.v)
			r.Remove(p)
			l.Put(p, struct{}{})
		}
		for l.Size() > x {
			p := l.Left().Key
			s -= int64(p.cnt) * int64(p.v)
			l.Remove(p)
			r.Put(p, struct{}{})
		}
		ans = append(ans, s)
		remove(nums[j])
		cnt[nums[j]]--
		add(nums[j])
	}
	return ans
